import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();
  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({ name: "", college_name: "", phone: "", email: "", event_id: eventId });
  const [userId, setUserId] = useState("");
  const [photo, setPhoto] = useState(null);
  const [faceDetected, setFaceDetected] = useState(false);
  const [registering, setRegistering] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  useEffect(() => {
    const loadModels = async () => {
      await faceapi.nets.tinyFaceDetector.loadFromUri("/models");
    };
    loadModels();
  }, []);

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setRegistering(true);
    try {
      const res = await axios.post("http://localhost:5000/register", formData);
      if (res.data.success) {
        setUserId(res.data.userId);
      } else {
        alert(res.data.message);
      }
    } catch (error) {
      alert("Registration failed");
    }
    setRegistering(false);
  };

  const openCamera = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    
    // Detection loop
    const detect = setInterval(async () => {
      const detections = await faceapi.detectAllFaces(videoRef.current, new faceapi.TinyFaceDetectorOptions());
      setFaceDetected(detections.length === 1);
    }, 500);
    videoRef.current.dataset.interval = detect;
  };

  const capturePhoto = () => {
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    canvas.getContext("2d").drawImage(videoRef.current, 0, 0);
    const image = canvas.toDataURL("image/png");
    setPhoto(image);

    // Stop Camera
    streamRef.current.getTracks().forEach(track => track.stop());
    clearInterval(parseInt(videoRef.current.dataset.interval));
  };

  const downloadCard = async () => {
    // 1. Upload photo to backend first
    try {
      await axios.put(`http://localhost:5000/update-photo/${userId}`, { photo });
    } catch (err) { console.error("Photo upload failed"); }

    // 2. Trigger Download
    const canvas = await html2canvas(idCardRef.current);
    const link = document.createElement("a");
    link.download = `ID_Card_${userId}.png`;
    link.href = canvas.toDataURL();
    link.click();
  };

  return (
    <div style={{ padding: "20px", textAlign: "center" }}>
      <Navbar />
      <h2>Event Registration</h2>

      {!userId ? (
        <form onSubmit={handleSubmit}>
          <input name="name" placeholder="Name" onChange={handleChange} required /><br/><br/>
          <input name="college_name" placeholder="College" onChange={handleChange} required /><br/><br/>
          <input name="phone" placeholder="Phone" onChange={handleChange} required /><br/><br/>
          <input name="email" placeholder="Email" onChange={handleChange} required /><br/><br/>
          <button type="submit" disabled={registering}>Register</button>
        </form>
      ) : (
        <div>
          <h3>Registration Successful!</h3>
          <button onClick={openCamera}>Open Camera</button>
          <video ref={videoRef} autoPlay width="320" height="240" />
          <p style={{ color: faceDetected ? "green" : "red" }}>{faceDetected ? "Face Detected" : "Look into camera..."}</p>
          <button onClick={capturePhoto} disabled={!faceDetected}>Capture Photo</button>
        </div>
      )}

      {photo && (
        <div style={{ marginTop: "30px" }}>
          <div ref={idCardRef} style={{ border: "2px solid black", width: "300px", padding: "15px", margin: "auto" }}>
            <h3>Event ID Card</h3>
            <p>Name: {formData.name}</p>
            <QRCode value={userId.toString()} size={100} />
            <img src={photo} alt="user" width="100" />
          </div>
          <button onClick={downloadCard}>Save & Download Card</button>
        </div>
      )}
      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
}

export default Register;
